const diff=["Média","Fácil","Difícil","Média","Fácil","Média","Difícil","Média","Fácil","Média","Difícil","Média","Fácil"] as const;
const expanded:Question[]=Object.entries(groups).flatMap(([topic,g])=>{
 const start=topic==="Formação Geral e Sociedade"?5:3;
 const expected=topic==="Formação Geral e Sociedade"?11:topic==="Modelagem de Banco de Dados"||topic==="Sistemas Embarcados"?15:13;
 if(g.items.length!==expected)throw Error("Quantidade incorreta: "+topic+" "+g.items.length);
 return g.items.map(([prompt,correct,explanation],i)=>{
  const wrong:string[]=[];
  for(let n=1;wrong.length<3;n++){const candidate=g.items[(i+n)%g.items.length][1];if(candidate!==correct&&!wrong.includes(candidate))wrong.push(candidate);}
  const answer=i%4, options=[...wrong];options.splice(answer,0,correct);
  return {id:g.prefix+(start+i),topic,difficulty:diff[i%diff.length],prompt,options:options as [string,string,string,string],answer,explanation};
 });
});
questionBank.push(...expanded);
